  "e": "Je moet een minimale ervaring van **twee overlandvluchten in dubbelbesturing** aantonen.\n\n**Wat zegt het KB?**\nDaarnaast vlieg je solo overland enkel onder de verantwoordelijkheid en met voorafgaande schriftelijke toelating van je instructeur. Ook voor solo lokale vluchten heb je die schriftelijke toelating nodig.\n\n**Valkuil:**\n5 uur overlandvluchten is een onderdeel van de vereisten voor de klassebevoegdverklaring, niet de voorwaarde voor je eerste solo overland.",
