  "c": 0,
  "e": "Je moet **ten minste 12 vlieguren als enige piloot** in de relevante ULM-klasse uitvoeren, met inbegrip van 12 starts en landingen.\n\n**Wat zegt het KB?**\nDe vergunning is geldig voor onbeperkte duur, zolang:\n- ze vergezeld is van een geldig medisch certificaat klasse 1, 2 of LAPL;\n- je binnen die 24 maanden de vlieguren hebt gemaakt;\n- je binnen die 24 maanden een herhalingstraining in vlucht met een instructeur hebt gevolgd.\n\n**Valkuil:**\nHet getal 6 komt ook in deze bepaling voor, maar het is niet het totaal over 24 maanden.",
