  "c": 0,
  "e": "Een voorrecht wordt samen met de klassebevoegdverklaring verlengd door een instructeur als je **via je persoonlijk vlieglogboek aantoont dat je het ten minste 6 uur hebt toegepast in de voorbije 2 jaar**.\n\n**Wat zegt het KB?**\nEen voorrecht dat niet meer geldig is, mag je niet meer uitoefenen tot je het opnieuw van een instructeur hebt verkregen.\n\n**Valkuil:**\nVoor het slepen van zweefvliegtuigen geldt een aparte regel: ten minste 15 slepingen in de voorbije 24 maanden.",
