  "c": 0,
  "e": "**Slepen van zweefvliegtuigen** staat niet in de lijst van voorrechten voor de autogiro.\n\n**Wat zegt het KB?**\nVoor de autogiro zijn de voorrechten: automatische piloot, drijvers, variabele spoed en vliegen met passagiers. Slepen van zweefvliegtuigen kan wel voor de klassen ULA en DPM.\n\n**In de praktijk:**\nVoor de ULH werkt het anders: daar is per type ultralichte helikopter een specifiek voorrecht nodig, en een bijkomend voorrecht om met een passagier te vliegen.",
