  "loText": "KB ULM 20/12/2024",
  "basis": "KB ULM",
  "q": "Wie moet de vluchten die je onder toezicht van een instructeur uitvoert, in je vliegboek medeondertekenen?",
  "o": [
   "De instructeur",
   "De examinator",
   "De eigenaar van de ULM",
   "Een beambte van het DGLV"
  ],
  "c": 0,
  "e": "Vluchten onder toezicht worden **door de instructeur medeondertekend** in je vliegboek.\n\n**Wat zegt het KB?**\nJe schrijft al je vluchten chronologisch in, telkens met de datum, het type ULM en de registratie, de duur, de plaatsen en tijdstippen van opstijgen en landen, en je functie (piloot, leerling-piloot of instructeur).\n\n**Valkuil:**\nEen onvolledig vliegboek kan een reden zijn om je ULM vergunning of een klassebevoegdverklaring te weigeren. Je legt het vliegboek ook voor aan de examinator vóór de afgifte van een nieuwe klassebevoegdverklaring.",
  "src": "kbulm",
  "ref": "KB ULM 20/12/2024, art. 76, § 2",
