  "q": "Je haalt in de lucht een trager toestel in. Hoe doe je dat volgens SERA?",
  "o": [
   "Je wijzigt je koers naar rechts en blijft uit de weg tot je volledig voorbij en vrij bent",
   "Je wijzigt je koers naar links, zoals bij inhalen op de weg",
   "Je klimt boven het andere toestel uit en blijft daar tot je voorbij bent",
   "Je wijzigt je koers naar rechts; zodra je naast het andere toestel vliegt, heeft het ingehaalde toestel geen voorrang meer"
  ],
  "c": 0,
  "e": "Je wijzigt je koers naar rechts en blijft uit de weg tot je volledig voorbij en vrij bent. Het ingehaalde toestel heeft voorrang.\n\n**Wat zegt SERA?**\nHet inhalende toestel blijft, of het nu klimt, daalt of horizontaal vliegt, uit de weg door naar rechts uit te wijken. Geen latere wijziging van de onderlinge posities ontslaat het van die verplichting tot het volledig voorbij en vrij is.\n\n**Valkuil:**\nLinks inhalen zoals op de weg is in de lucht verkeerd. En ook als je naast het andere toestel komt te vliegen, blijft jij degene die moet uitwijken.",
