  "lo": "SERA",
  "loText": "",
  "basis": "SERA",
  "q": "Je wilt zonder bijzondere klaring VFR opstijgen van een luchtvaartterrein in een plaatselijk luchtverkeersleidingsgebied (CTR). Onder welke gerapporteerde wolkenbasis (ceiling) mag dat niet zonder klaring van de luchtverkeersleiding?",
  "o": [
   "1 500 ft (450 m)",
   "1 000 ft (300 m)",
   "600 ft (180 m)",
   "3 000 ft (900 m)"
  ],
  "c": 0,
  "e": "1 500 ft (450 m). Is de gerapporteerde wolkenbasis lager, dan mag je in een CTR niet VFR opstijgen of landen zonder klaring van de luchtverkeersleiding.\n\n**Wat zegt SERA?**\nOnder een wolkenbasis van 450 m (1 500 ft) of een grondzicht van minder dan 5 km mag je niet opstijgen, landen of het ATZ of circuit binnenvliegen, tenzij de luchtverkeersleiding je een klaring geeft.\n\n**Valkuil:**\n600 ft is de wolkenbasis waaronder de luchtverkeersleiding ook geen bijzondere VFR-klaring (special VFR) meer mag geven om op te stijgen of te landen. Tussen 600 ft en 1 500 ft is dus alleen special VFR mogelijk.\n\n**In de praktijk:**\nLees de METAR: de ceiling is de laagste laag BKN of OVC.",
