  "lo": "SERA",
  "loText": "",
  "basis": "SERA",
  "q": "Wat is in principe het hoogste vliegniveau waarop je VFR mag vliegen?",
  "o": [
   "FL 195; daarboven alleen in een luchtruimreservering of met toestemming van de verantwoordelijke ATS-eenheid tot FL 285",
   "FL 100; daarboven is IFR verplicht",
   "FL 285, zonder verdere voorwaarden",
   "Er is geen bovengrens, zolang je VMC hebt"
  ],
  "c": 0,
  "e": "FL 195. VFR-vluchten worden niet boven FL 195 uitgevoerd, behalve in uitzonderingen.\n\n**Wat zegt SERA?**\nUitzonderingen zijn een luchtruimreservering waar de lidstaat VFR toelaat, of luchtruim tot en met FL 285 als de verantwoordelijke ATS-eenheid het VFR-verkeer toelaat volgens procedures in de AIP. Al het luchtruim boven FL 195 is klasse C.\n\n**Valkuil:**\nFL 285 is geen gewone bovengrens. Je hebt daarvoor een specifieke toestemming nodig.\n\n**In de praktijk:**\nVoor een lesvliegtuig of ULM is dit theorie. Het verklaart wel waarom de VMC-tabel ook voor hoge niveaus waarden geeft.",
