  "basis": "SERA",
  "q": "Wat is de minimale hoogte voor een VFR-vlucht boven een dichtbevolkte stad (behalve bij opstijgen en landen of met toestemming)?",
  "o": [
   "1 000 ft (300 m) boven de hoogste hindernis binnen een straal van 600 m rond het luchtvaartuig",
   "500 ft (150 m) boven de hoogste hindernis binnen een straal van 150 m rond het luchtvaartuig",
   "1 000 ft (300 m) boven de grond, recht onder het luchtvaartuig",
   "1 500 ft (450 m) boven de hoogste hindernis binnen een straal van 8 km"
  ],
  "c": 0,
  "e": "1 000 ft (300 m) boven de hoogste hindernis binnen een straal van 600 m rond het luchtvaartuig.\n\n**Wat zegt SERA?**\nBehalve wanneer het nodig is om op te stijgen of te landen, of met toestemming van de bevoegde autoriteit, vlieg je boven dichtbevolkte zones van steden, gemeenten of nederzettingen niet lager dan 1 000 ft boven de hoogste hindernis binnen 600 m.\n\n**Valkuil:**\nDe referentie is niet de grond onder je, maar de hoogste hindernis binnen 600 m: een kerktoren of flatgebouw naast je route telt mee.\n\n**In de praktijk:**\nKijk vooraf welke hoge gebouwen of masten er in de stad staan.",
