  "lo": "SERA",
  "loText": "",
  "basis": "SERA",
  "q": "Je vliegt VFR overdag boven open akkerland, ver van bebouwing. Wat is de minimale hoogte (behalve bij opstijgen en landen of met toestemming)?",
  "o": [
   "500 ft (150 m) boven de grond of het water, of boven de hoogste hindernis binnen een straal van 150 m",
   "1 000 ft (300 m) boven de hoogste hindernis binnen een straal van 600 m",
   "300 ft (90 m) boven de grond",
   "500 ft (150 m) boven de hoogste hindernis binnen een straal van 8 km"
  ],
  "c": 0,
  "e": "500 ft (150 m) boven de grond of het water, of 500 ft boven de hoogste hindernis binnen een straal van 150 m (500 ft) rond het luchtvaartuig.\n\n**Wat zegt SERA?**\nBuiten bebouwde gebieden en mensenmassa's mag een VFR-vlucht niet lager dan 150 m (500 ft) vliegen. Uitzonderingen zijn opstijgen en landen, of toestemming van de bevoegde autoriteit.\n\n**Valkuil:**\n1 000 ft binnen 600 m geldt alleen boven bebouwde gebieden en openluchtbijeenkomsten.\n\n**In de praktijk:**\nStaat er een hoogspanningsmast van 150 ft binnen 150 m van je route, dan moet je minstens 650 ft boven de grond vliegen.",
