  "basis": "SERA",
  "q": "Je vliegt VFR over een muziekfestival in een weiland, ver buiten de bebouwde kom. Welke minimumhoogte geldt boven die mensenmassa?",
  "o": [
   "Dezelfde minimumhoogte als boven de dichtbebouwde zone van een stad",
   "500 ft boven de grond, want het festival ligt buiten de bebouwde kom",
   "500 ft boven de hoogste hindernis binnen 150 m",
   "Er geldt geen bijzondere regel als het evenement niet in de NOTAM staat"
  ],
  "c": 0,
  "e": "Dezelfde als boven een stad: 1 000 ft (300 m) boven de hoogste hindernis binnen een straal van 600 m.\n\n**Wat zegt SERA?**\nDe strengere regel geldt boven dichtbevolkte zones van steden, gemeenten of nederzettingen en ook boven een openluchtbijeenkomst van personen (open-air assembly of persons). Waar die bijeenkomst plaatsvindt, maakt niet uit.\n\n**Valkuil:**\nOok een festival in het open veld is een openluchtbijeenkomst. Het feit dat je buiten de bebouwde kom vliegt, verandert daar niets aan.\n\n**In de praktijk:**\nBij een motorpanne boven een menigte heb je geen landingsplaats. Ruim boven of naast de menigte vliegen is ook goed airmanship.",
