  "basis": "SERA",
  "q": "Je vliegt boven een gecontroleerd luchtvaartterrein zonder radiocontact. De toren richt een wit knipperlicht op je. Wat betekent dit?",
  "o": [
   "Land op dit luchtvaartterrein en begeef je naar het platform; klaringen om te landen en te taxiën volgen te zijner tijd",
   "Het luchtvaartterrein is onveilig, land niet",
   "Je bent geklaard om onmiddellijk te landen op de baan in gebruik",
   "Vlieg verder naar je bestemming, je mag het gebied verlaten"
  ],
  "c": 0,
  "e": "Een wit knipperlicht naar een luchtvaartuig in de vlucht betekent: land op dit luchtvaartterrein en begeef je naar het platform.\n\n**Wat zegt SERA?**\nBij dit sein vermeldt de tabel dat de klaringen om te landen en te taxiën te zijner tijd worden gegeven. Het witte knipperlicht is dus nog geen landingsklaring.\n\n**In de praktijk:**\nVoeg in het circuit in en wacht op het ononderbroken groene licht voordat je effectief landt.\n\n**Valkuil:**\nDe eigenlijke landingsklaring is ononderbroken groen. Het witte knipperlicht zegt alleen dat je hier moet landen en daarna naar het platform moet gaan.",
