  "basis": "SERA",
  "q": "Je ziet in het signaalgebied van een luchtvaartterrein een horizontale witte halter (zonder dwarsbalken). Wat betekent dit?",
  "o": [
   "Landen, opstijgen en taxiën is alleen toegestaan op banen en taxibanen",
   "Alleen landen en opstijgen moeten op banen gebeuren; taxiën mag ook daarbuiten",
   "Het luchtvaartterrein is gesloten voor alle verkeer",
   "Bochten in het circuit moeten naar rechts worden gemaakt"
  ],
  "c": 0,
  "e": "Een witte halter in het signaalgebied betekent dat landen, opstijgen en taxiën uitsluitend op banen en taxibanen mag.\n\n**Wat zegt SERA?**\nBij een halter met een zwarte dwarsbalk door elk rond uiteinde moeten alleen landen en opstijgen op banen gebeuren; andere bewegingen, zoals taxiën, zijn dan niet beperkt tot banen en taxibanen.\n\n**In de praktijk:**\nOp terreinen met grasvlakken naast de banen mag je bij dit sein dus niet over het gras rijden of afsnijden.\n\n**Valkuil:**\nDe vrijheid om buiten de taxibanen te taxiën hoort bij de halter met zwarte balken, niet bij de gewone witte halter.",
  "src": "sera",
