  "basis": "SERA",
  "q": "Op een deel van een taxibaan ligt een groot wit kruis in één kleur. Wat betekent dit?",
  "o": [
   "Dat deel is ongeschikt voor bewegingen van luchtvaartuigen",
   "Je moet daar stoppen en wachten op toestemming van de toren",
   "Daar kruisen een baan en een taxibaan elkaar",
   "Daar mogen alleen zweefvliegtuigen bewegen"
  ],
  "c": 0,
  "e": "Gele of witte kruisen in één kleur, horizontaal op banen of taxibanen, betekenen dat dat gebied ongeschikt is voor bewegingen van luchtvaartuigen.\n\n**Wat zegt SERA?**\nHet gaat om een gesloten baan of taxibaan, of een gesloten deel ervan.\n\n**In de praktijk:**\nTaxi of land nooit op een gedeelte dat met een kruis gemarkeerd is, ook al lijkt het oppervlak in orde. Er kunnen werken of schade zijn die je vanuit de lucht niet ziet.\n\n**Valkuil:**\nEen dubbel wit kruis in het signaalgebied gaat over zweefvliegen. Een enkel kruis op de baan of taxibaan zelf betekent: gesloten.",
  "src": "sera",
  "ref": "SERA Aanhangsel 1 – Signalen (oorspronkelijke tekst 2012)",
  "doc": "sera2012",
