  "lo": "SERA",
  "loText": "",
  "basis": "SERA",
  "q": "In het signaalgebied van een luchtvaartterrein ligt een pijl in een opvallende kleur die naar rechts wijst. Wat betekent dit voor jou?",
  "o": [
   "Vóór het landen en na het opstijgen moet je alle bochten naar rechts maken",
   "Na de landing moet je de baan naar rechts verlaten",
   "De wind waait van rechts; verwacht zijwind bij de landing",
   "Je moet het luchtvaartterrein aan de rechterkant ontwijken"
  ],
  "c": 0,
  "e": "Een pijl naar rechts in het signaalgebied (of horizontaal aan het einde van de baan in gebruik) betekent dat je vóór het landen en na het opstijgen elke bocht naar rechts maakt: een rechtshandig circuit.\n\n**Wat zegt SERA?**\nDe standaardregel is dat je bij het naderen en vertrekken bochten naar links maakt, tenzij anders aangegeven. De pijl naar rechts geeft die andere aanwijzing.\n\n**Valkuil:**\nDe pijl zegt niets over het verlaten van de baan of over de wind. Ze gaat alleen over de draairichting in het circuit.",
  "src": "sera",
  "ref": "SERA Aanhangsel 1 – Signalen (oorspronkelijke tekst 2012)",
  "doc": "sera2012",
  "art": "Aanhangsel 1",
  "citaat": "geeft een pijl naar rechts, in een opvallende kleur (figuur A1-9), aan dat vóór het landen en na het opstijgen iedere bocht naar rechts moet worden gemaakt.",
  "opgesteld": "AI (Claude), op basis van de wettekst",
