  "basis": "SERA",
  "q": "Je dient tijdens de vlucht een vluchtplan in om een controlegebied (CTA) binnen te vliegen. Wanneer moet de bevoegde luchtverkeersdienst het uiterlijk ontvangen hebben?",
  "o": [
   "Minstens 10 minuten voordat je naar verwachting het punt van binnenkomst bereikt",
   "Minstens 60 minuten voordat je het punt van binnenkomst bereikt",
   "Minstens 2 minuten voordat je het punt van binnenkomst bereikt",
   "Op het moment dat je de grens van het controlegebied overvliegt"
  ],
  "c": 0,
  "e": "De dienst moet het vluchtplan minstens 10 minuten voordat je naar verwachting het punt van binnenkomst in het controlegebied (of het kruispunt met een luchtweg) bereikt, ontvangen hebben.\n\n**Wat zegt SERA?**\nEen vluchtplan dat tijdens de vlucht wordt ingediend, moet zo vroeg worden doorgegeven dat de bevoegde ATS-eenheid het minstens 10 minuten vóór dat punt ontvangt.\n\n**In de praktijk:**\nRoep dus tijdig op, niet pas vlak voor de grens. Zo krijg je tijd om een klaring te ontvangen en hoef je niet te cirkelen.\n\n**Valkuil:**\nDe 60 minuten gelden voor een vluchtplan dat je vóór vertrek indient, niet voor een vluchtplan in de lucht.",
