  "lo": "SERA",
  "loText": "",
  "basis": "SERA",
  "q": "Je VFR-vlucht vertrekt vanaf een gecontroleerd luchtvaartterrein en verloopt als gecontroleerde vlucht. Door een technisch probleem loop je vertraging op. Vanaf welke vertraging ten opzichte van de geschatte off-blocktijd moet je het vluchtplan wijzigen of vervangen?",
  "o": [
   "30 minuten",
   "1 uur",
   "10 minuten",
   "3 uur"
  ],
  "c": 0,
  "e": "Voor een gecontroleerde vlucht moet het vluchtplan gewijzigd of vervangen worden bij een vertraging van 30 minuten ten opzichte van de EOBT.\n\n**Wat zegt SERA?**\nBij een vertraging van 30 minuten (gecontroleerde vlucht) of 1 uur (ongecontroleerde vlucht) wijzig je het vluchtplan, of je dient een nieuw in en annuleert het oude.\n\n**In de praktijk:**\nWacht niet tot de grens bereikt is: zie je dat je de tijd niet haalt, pas het vluchtplan dan meteen aan.\n\n**Valkuil:**\nDe 1 uur geldt voor een ongecontroleerde vlucht. Zodra je vlucht gecontroleerd is, geldt de strengere grens van 30 minuten.",
