  "q": "Welk element neem je alleen in je aankomstmelding op als je een uitwijklanding hebt gemaakt?",
  "o": [
   "Het luchtvaartterrein van bestemming",
   "Het luchtvaartterrein van vertrek",
   "Het tijdstip van aankomst",
   "De identificatie van het luchtvaartuig"
  ],
  "c": 0,
  "e": "Het luchtvaartterrein van bestemming vermeld je alleen bij een uitwijklanding. Dan verschilt het van het luchtvaartterrein van aankomst.\n\n**Wat zegt SERA?**\nEen aankomstmelding bevat: identificatie van het luchtvaartuig, vertrekluchtvaartterrein, bestemming (alleen bij een uitwijklanding), luchtvaartterrein van aankomst en tijdstip van aankomst.\n\n**In de praktijk:**\nLand je elders dan gepland, dan moet de dienst weten dat je veilig bent geland en dat de oorspronkelijke bestemming je niet meer verwacht.\n\n**Valkuil:**\nVertrekveld, aankomsttijd en identificatie horen altijd in de melding, niet alleen bij een uitwijklanding.",
