  "c": 0,
  "e": "Z: de vlucht begint onder VFR en wijzigt daarna een of meer keren van vliegregels.\n\n**Wat zegt SERA?**\nVoor de vliegregels in vak 8 gebruik je:\n- I: hele vlucht IFR\n- V: hele vlucht VFR\n- Y: eerst IFR, daarna wijziging(en)\n- Z: eerst VFR, daarna wijziging(en)\nIn vak 15 vermeld je het punt of de punten waar de wijziging van vliegregels gepland is.\n\n**Valkuil:**\nY en Z worden vaak verwisseld. De letter zegt met welke vliegregels de vlucht begint: Z begint VFR, Y begint IFR.",
