  "c": 0,
  "e": "G staat voor algemene luchtvaart (general aviation), zoals een privé- of clubvlucht.\n\n**Wat zegt SERA?**\nVoor de soort vlucht in vak 8 gebruik je:\n- S: lijndienst\n- N: niet-geregeld luchtvervoer\n- G: algemene luchtvaart\n- M: militair\n- X: overige\n\n**Valkuil:**\nN lijkt op 'niet-commercieel', maar betekent niet-geregeld luchtvervoer (bv. charter). X is alleen voor vluchten die in geen enkele categorie passen. Een privévlucht is gewoon algemene luchtvaart.",
