  "e": "Je vult ZZZZ in en vermeldt in vak 18 naam en ligging van het veld na DEP/ (voor de bestemming in vak 16 is dat DEST/).\n\n**Wat zegt SERA?**\nHeeft een veld geen locatie-indicator, dan vul je ZZZZ in en geef je de details in vak 18. Een veld dat niet in de AIP staat, geef je aan met coördinaten (bv. 4620N07805W) of met peiling en afstand vanaf het dichtstbijzijnde significante punt.\n\n**Valkuil:**\nAFIL gebruik je alleen voor een vluchtplan dat je in de lucht indient, niet voor een veld zonder code.",
