  "q": "Je vertrekt vanaf een ongecontroleerd veld en je vluchtplan vermeldt dat je later een CTR van klasse D doorkruist. Wanneer moet je de klaring verkrijgen?",
  "o": [
   "Vóór je het gebied binnenvliegt waar de gecontroleerde vlucht begint",
   "Vóór vertrek, telefonisch, vanaf het ongecontroleerde veld",
   "Niet nodig: met een ingediend vluchtplan geldt de klaring automatisch",
   "Binnen 2 minuten na het binnenvliegen van de CTR"
  ],
  "c": 0,
  "e": "Je verkrijgt de klaring van de bevoegde verkeersleidingseenheid vóór je het gebied binnenvliegt waar de gecontroleerde vlucht begint.\n\n**Wat zegt SERA?**\nVóór je een gecontroleerde vlucht, of een deel van een vlucht als gecontroleerde vlucht, uitvoert, moet je een klaring hebben. Is het eerste deel ongecontroleerd, dan vraag je de klaring vóór je het gecontroleerde gebied binnengaat.\n\n**In de praktijk:**\nRoep tijdig op en blijf buiten de CTR tot je de klaring hebt ontvangen.\n\n**Valkuil:**\nEen ingediend vluchtplan is geen klaring. Het vluchtplan is alleen de manier om een klaring aan te vragen.",
