  "c": 0,
  "e": "Je meldt matige en zware turbulentie.\n\n**Wat zegt SERA?**\nAlle luchtvaartuigen moeten een speciale waarneming doen en melden bij onder meer: matige of zware turbulentie, matige of zware ijsafzetting, zware berggolven, onweersbuien (met of zonder hagel) die verborgen, ingebed of wijdverspreid zijn of in buienlijnen voorkomen, zware stof- of zandstormen, vulkanische aswolken en vulkanische activiteit, en een remwerking op de baan die slechter is dan gemeld.\n\n**In de praktijk:**\nJe melding wordt doorgegeven aan ander verkeer en aan de meteorologische dienst.\n\n**Valkuil:**\nNiet alleen zware turbulentie: ook matige turbulentie moet je melden.",
