  "c": 0,
  "e": "Een remwerking op de baan die slechter is dan gemeld, is een speciale waarneming die je moet melden.\n\n**Wat zegt SERA?**\nOok vulkanische aswolken, vulkanische activiteit vóór een uitbarsting of een uitbarsting, zware berggolven en matige of zware ijsafzetting moeten als speciale waarneming gemeld worden. Een melding over de remwerking die niet strookt met het baanconditierapport stuurt de luchtverkeersdienst onmiddellijk door naar de exploitant van het luchtvaartterrein.\n\n**Valkuil:**\nIjsafzetting moet je pas vanaf matige sterkte als speciale waarneming melden, niet bij lichte ijsafzetting.",
