  "basis": "SERA",
  "q": "In de eindnadering krijg je te maken met duidelijke windschering, die niet in de lijst van speciale waarnemingen staat. Wat schrijft SERA voor?",
  "o": [
   "Als je vindt dat het de veiligheid van ander verkeer kan beïnvloeden, meld je het zo snel als praktisch mogelijk aan de luchtverkeersdienst",
   "Niets: alleen omstandigheden uit de lijst van speciale waarnemingen moeten gemeld worden",
   "Je meldt het alleen schriftelijk na de vlucht aan de meteorologische dienst",
   "Je meldt het alleen als de verkeersleider erom vraagt"
  ],
  "c": 0,
  "e": "Kan de windschering naar jouw oordeel de veiligheid of de efficiëntie van ander verkeer beïnvloeden, dan meld je het zo snel als praktisch mogelijk aan de luchtverkeersdienst.\n\n**Wat zegt SERA?**\nNaast de lijst van speciale waarnemingen bestaan er andere niet-routinematige waarnemingen. Windschering is het voorbeeld dat SERA noemt. Hier beslist de gezagvoerder of melden nodig is.\n\n**In de praktijk:**\nJe melding helpt het verkeer achter je in de nadering. Waarnemingen meld je tijdens de vlucht op het moment zelf of zo snel mogelijk daarna.\n\n**Valkuil:**\nDe lijst van speciale waarnemingen is niet alles wat je meldt: ook andere gevaarlijke weersverschijnselen horen gemeld te worden.",
